# Bid document types renamed in November 2026: the product specification is
# now the technical datasheet (TDS), and "Certificate or licence" split into
# the Certificate of Analysis (COA) and the licence. Stored values follow.
RENAMED = {"Product specification": "Technical datasheet",
           "Certificate or licence": "Certificate of Analysis"}


def rename_doc_types(apps, schema_editor):
    Document = apps.get_model("core", "Document")
    Tender = apps.get_model("core", "Tender")
    for old, new in RENAMED.items():
        Document.objects.filter(doc_type=old).update(doc_type=new)
    for t in Tender.objects.exclude(required_docs=[]):
        docs = [RENAMED.get(d, d) for d in (t.required_docs or [])]
        docs = list(dict.fromkeys(docs))
        if docs != t.required_docs:
            t.required_docs = docs
            t.save(update_fields=["required_docs"])


def grant_contracts(apps, schema_editor):
    """Setting a vendor's contract is new (supplier.contract). Any role a
    company has re-scoped keeps its own list, so the new capability is added
    where the role could already prequalify vendors: the same people."""
    OrgSetting = apps.get_model("core", "OrgSetting")
    AccessRole = apps.get_model("core", "AccessRole")
    row = OrgSetting.objects.filter(pk=1).first()
    if row and isinstance((row.data or {}).get("roles"), dict):
        data = dict(row.data)
        changed = False
        for key, o in data["roles"].items():
            perms = o.get("perms") if isinstance(o, dict) else None
            if isinstance(perms, list) and "supplier.prequalify" in perms and "supplier.contract" not in perms:
                o["perms"] = perms + ["supplier.contract"]
                changed = True
        if changed:
            row.data = data
            row.save(update_fields=["data"])
    for r in AccessRole.objects.all():
        if "supplier.prequalify" in (r.perms or []) and "supplier.contract" not in r.perms:
            r.perms = list(r.perms) + ["supplier.contract"]
            r.save(update_fields=["perms"])


